/** Join optional classes without coupling the component source to a utility package. */
export function cn(...classes: Array<string | false | null | undefined>) {
  return classes.filter(Boolean).join(' ')
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { createContext, useContext, useMemo, type ReactNode } from 'react'
import {
  formattingLocales,
  messagesFor,
  translate,
  type Locale,
  type Translator,
  type Translations,
} from './locale'
import { uiMessages } from './ui-messages'
export * from './locale'

type I18nValue = {
  locale: Locale
  formatLocale: string
  t: Translator
  /** Whether this provider (built-in labels or application `messages`) translates the text. */
  has: (message: string) => boolean
  setLocale: (locale: Locale) => void
  pending: boolean
}
const fallback: I18nValue = {
  locale: 'ko',
  formatLocale: 'ko-KR',
  t: (message, values) => translate(message, {}, values),
  has: () => false,
  setLocale: () => {},
  pending: false,
}
const I18nContext = createContext<I18nValue>(fallback)

/**
 * Optional and isolated: components keep their Korean defaults without a locale provider.
 * Only built-in component labels live here. Block copy ships with the blocks (block-i18n),
 * so an application that installs a single component does not bundle every block's text.
 */
export function MoruLocaleProvider({
  locale: localeProp,
  messages,
  onLocaleChange,
  pending = false,
  children,
}: {
  locale?: Locale
  messages?: Translations
  onLocaleChange?: (locale: Locale) => void
  pending?: boolean
  children: ReactNode
}) {
  const parent = useContext(I18nContext)
  const locale = localeProp ?? parent.locale
  const value = useMemo<I18nValue>(() => {
    const dictionary = {
      ...messagesFor(uiMessages, locale),
      ...messages,
    }
    return {
      locale,
      formatLocale: formattingLocales[locale],
      t: (message, values) => translate(message, dictionary, values),
      has: (message) => Object.prototype.hasOwnProperty.call(dictionary, message),
      setLocale: onLocaleChange ?? fallback.setLocale,
      pending,
    }
  }, [locale, messages, onLocaleChange, pending])
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}
export function useI18n() {
  return useContext(I18nContext)
}

// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
export const locales = ['ko', 'en', 'ja', 'zh-CN'] as const
export type Locale = (typeof locales)[number]
export type TranslationValues = Record<string, string | number>
export type Translations = Record<string, string>
export type MessageCatalog = Record<string, { en: string; ja: string; 'zh-CN': string }>
export type Translator = (message: string, values?: TranslationValues) => string

export const localeNames: Record<Locale, string> = {
  ko: '한국어',
  en: 'English',
  ja: '日本語',
  'zh-CN': '简体中文',
}
export const formattingLocales: Record<Locale, string> = {
  ko: 'ko-KR',
  en: 'en-US',
  ja: 'ja-JP',
  'zh-CN': 'zh-CN',
}
export function isLocale(value: unknown): value is Locale {
  return typeof value === 'string' && locales.includes(value as Locale)
}
export function resolveLocale(languages: readonly string[]): Locale {
  for (const language of languages) {
    const code = language.toLowerCase().split('-')[0]
    if (code === 'zh') return 'zh-CN'
    if (code === 'ko' || code === 'en' || code === 'ja') return code
  }
  return 'ko'
}
/** Named placeholders keep sentence order in the translation, outside application logic. */
export function translate(message: string, messages: Translations, values?: TranslationValues) {
  const translated = Object.prototype.hasOwnProperty.call(messages, message)
    ? messages[message]
    : message
  return values
    ? translated.replace(/\{(\w+)\}/g, (placeholder, key) =>
        Object.prototype.hasOwnProperty.call(values, key) ? String(values[key]) : placeholder,
      )
    : translated
}
export function messagesFor(catalog: MessageCatalog, locale: Locale): Translations {
  return locale === 'ko'
    ? {}
    : Object.fromEntries(
        Object.entries(catalog).map(([source, translations]) => [source, translations[locale]]),
      )
}

export const koreanTranslator: Translator = (message, values) => translate(message, {}, values)

