  const result = validateComponentSpacing(tokens.componentSpacing)
  if (
    !targetIds.has(key) ||
    !componentSpacingTargets.find((target) => target.id === key)?.selector ||
    !boxes.includes(box) ||
    !spacingSides.includes(side)
