  const result: Record<string, string> = {}
  const safe = validateComponentSpacing(overrides)
  for (const { id } of componentSpacingTargets) {
    for (const box of boxes)
      for (const side of spacingSides) {
        const length = safe[id]?.[box]?.[side]
